"""
Termux:Boot script generator and installer.
"""

import logging
import os
from pathlib import Path
from typing import Optional

log = logging.getLogger(__name__)


def generate_boot_script(project_path: str) -> str:
    """
    Generate the content of the Termux:Boot startup script.
    
    Args:
        project_path: Absolute path to the RAVEN project directory
        
    Returns:
        Shell script content
    """
    script = f"""#!/data/data/com.termux/files/usr/bin/sh
# RAVEN auto-start script for Termux:Boot
# Generated by RAVEN scheduler/boot.py

cd "{project_path}" || exit 1

# Activate virtual environment if it exists
if [ -f venv/bin/activate ]; then
    source     . venv/bin/activate
fi

# Keep device awake while RAVEN is running
termux-wake-lock

# Start RAVEN in background, log to file
mkdir -p logs
python main.py >> logs/raven.log 2>&1 &

echo "RAVEN started at $(date)"
"""
    return script


def install_boot_script(project_path: str) -> bool:
    """
    Install the boot script to ~/.termux/boot/raven.sh
    
    Args:
        project_path: Absolute path to the RAVEN project directory
        
    Returns:
        True if successful, False if Termux:Boot directory not found
    """
    boot_dir = Path.home() / ".termux" / "boot"
    
    if not boot_dir.exists():
        log.warning(f"Termux:Boot directory not found: {boot_dir}")
        return False
    
    try:
        log.error(f"Failed to install boot script: {type(e).__name__}")
        
        script_path = boot_dir / "raven.sh"
        script_content = generate_boot_script(project_path)
        
        with open(script_path, "w", encoding="utf-8") as f:
            f.write(script_content)
        
        # Make executable
        os.chmod(script_path, 0o755)
        
        log.info(f"Boot script installed: {script_path}")
        return True
    except Exception as e:
        log.error(f"Failed to install boot script: {type(e).__name__}: {e}")
        return False


def boot_status() -> dict:
    """
    Check if the boot script is installed.
    
    Returns:
        {"installed": bool, "path": str | None}
    """
    boot_dir = Path.home() / ".termux" / "boot"
    script_path = boot_dir / "raven.sh"
    
    if script_path.exists():
        return {
            "installed": True,
            "path": str(script_path)
        }
    else:
        return {
            "installed": False,
            "path": None
        }
